  "FiniteJetOver.StrictLoc.locRhoC_surjective": {
    "html": "<div class=\"lean-knowl-head\"><span class=\"lean-decl-kind\">theorem</span> <code>FiniteJetOver.StrictLoc.locRhoC_surjective</code></div><div class=\"lean-doc\"><p><code>𝓒_α → 𝓓_α</code> is a continuous open surjection ([FJP] Prop 4.5: &quot;<code>C_α → D_α</code> is a strict<br>surjection&quot;).</p></div><pre class=\"lean-source\"><code class=\"language-lean\">theorem locRhoC_surjective (hspan : Ideal.span ({g} ∪ Set.range f) = ⊤) :\n    Function.Surjective (locRhoC K m g f)</code></pre><div class=\"lean-source-meta\">projects/AdicSpaces/Adic spaces/FJP/Over/StrictLocalization.lean:1122–1123 · commit b007a4f3d422</div>",
    "href": "./lean/AdicSpaces/declarations/FiniteJetOver.StrictLoc.locRhoC_surjective.html"
  },
  "FiniteJetOver.StrictLoc.loc_pair_isEmbedding": {
    "html": "<div class=\"lean-knowl-head\"><span class=\"lean-decl-kind\">theorem</span> <code>FiniteJetOver.StrictLoc.loc_pair_isEmbedding</code></div><div class=\"lean-doc\"><p>Topological strictness on the left ([FJP] (4.19)/(4.20)): <code>𝓐_α</code> carries the subspace<br>topology of <code>𝓑_α × 𝓒_α</code>.</p></div><pre class=\"lean-source\"><code class=\"language-lean\">theorem loc_pair_isEmbedding (ϖ : Uniformizer K) (hK₀ : IsNoetherianRing (unitBall K))\n    (hspan : Ideal.span ({g} ∪ Set.range f) = ⊤) :\n    Topology.IsEmbedding\n      (fun x : locA K m g f =&gt; (locJB K m g f x, locIotaC K m g f x))</code></pre><div class=\"lean-source-meta\">projects/AdicSpaces/Adic spaces/FJP/Over/StrictLocalization.lean:1094–1097 · commit b007a4f3d422</div>",
    "href": "./lean/AdicSpaces/declarations/FiniteJetOver.StrictLoc.loc_pair_isEmbedding.html"
  },
  "FiniteJetOver.StrictLoc.loc_row_exact": {
    "html": "<div class=\"lean-knowl-head\"><span class=\"lean-decl-kind\">theorem</span> <code>FiniteJetOver.StrictLoc.loc_row_exact</code></div><div class=\"lean-doc\"><p>Algebraic exactness of the localized row: the pullback description of <code>𝓐_α</code><br>([FJP] (4.20)).</p></div><pre class=\"lean-source\"><code class=\"language-lean\">theorem loc_row_exact (ϖ : Uniformizer K) (hK₀ : IsNoetherianRing (unitBall K))\n    (hspan : Ideal.span ({g} ∪ Set.range f) = ⊤)\n    (b : locB K m g f) (c : locC K m g f)\n    (h : locRhoB K m g f b = locRhoC K m g f c) :\n    ∃! x : locA K m g f, locJB K m g f x = b ∧ locIotaC K m g f x = c</code></pre><div class=\"lean-source-meta\">projects/AdicSpaces/Adic spaces/FJP/Over/StrictLocalization.lean:942–946 · commit b007a4f3d422</div>",
    "href": "./lean/AdicSpaces/declarations/FiniteJetOver.StrictLoc.loc_row_exact.html"
  },
